   599	  inline bool create (const OT::cff1::accelerator_subset_t &acc,
   600	                      hb_subset_plan_t *plan)
   601	  {
   602	     /* make sure notdef is first */
   603	    if ((plan->glyphs.len == 0) || (plan->glyphs[0] != 0)) return false;
   604	
   605	    final_size = 0;
   606	    num_glyphs = plan->glyphs.len;
   607	    orig_fdcount = acc.fdCount;
   608	    drop_hints = plan->drop_hints;
   609	    desubroutinize = plan->desubroutinize;
   610	
   611	    /* check whether the subset renumbers any glyph IDs */
   612	    gid_renum = false;
   613	    for (unsigned int glyph = 0; glyph < plan->glyphs.len; glyph++)
   614	    {
   615	      if (plan->glyphs[glyph] != glyph) {
   616	        gid_renum = true;
   617	        break;
   618	      }
   619	    }
   620	
   621	    subset_charset = gid_renum || !acc.is_predef_charset ();
   622	    subset_encoding = !acc.is_CID() && !acc.is_predef_encoding ();
   623	
   624	    /* CFF header */
   625	    final_size += OT::cff1::static_size;
   626	
   627	    /* Name INDEX */
   628	    offsets.nameIndexOffset = final_size;
   629	    final_size += acc.nameIndex->get_size ();
   630	
   631	    /* top dict INDEX */
   632	    {
   633	      /* Add encoding/charset to a (copy of) top dict as necessary */
   634	      topdict_mod.init (&acc.topDict);
   635	      bool need_to_add_enc = (subset_encoding && !acc.topDict.has_op (OpCode_Encoding));
   636	      bool need_to_add_set = (subset_charset && !acc.topDict.has_op (OpCode_charset));
   637	      if (need_to_add_enc || need_to_add_set)
   638	      {
   639	        if (need_to_add_enc)
   640	          topdict_mod.add_op (OpCode_Encoding);
   641	        if (need_to_add_set)
   642	          topdict_mod.add_op (OpCode_charset);
   643	      }
   644	      offsets.topDictInfo.offset = final_size;
   645	      CFF1TopDict_OpSerializer topSzr;
   646	      unsigned int topDictSize = TopDict::calculate_serialized_size (topdict_mod, topSzr);
   647	      offsets.topDictInfo.offSize = calcOffSize(topDictSize);
   648	      if (unlikely (offsets.topDictInfo.offSize > 4))
   649	        return false;
   650	      final_size += CFF1IndexOf<TopDict>::calculate_serialized_size<CFF1TopDictValuesMod>
   651	                                                (offsets.topDictInfo.offSize,
   652	                                                 &topdict_mod, 1, topdict_sizes, topSzr);
   653	    }
   654	
   655	    /* Determine re-mapping of font index as fdmap among other info */
   656	    if (acc.fdSelect != &Null(CFF1FDSelect))
   657	    {
   658	        if (unlikely (!hb_plan_subset_cff_fdselect (plan->glyphs,
   659	                                  orig_fdcount,
   660	                                  *acc.fdSelect,
   661	                                  subset_fdcount,
   662	                                  offsets.FDSelectInfo.size,
   663	                                  subset_fdselect_format,
   664	                                  subset_fdselect_ranges,
   665	                                  fdmap)))
   666	        return false;
   667	    }
   668	    else
   669	      fdmap.identity (1);
   670	
   671	    /* remove unused SIDs & reassign SIDs */
   672	    {
   673	      /* SIDs for name strings in dicts are added before glyph names so they fit in 16-bit int range */
   674	      if (unlikely (!collect_sids_in_dicts (acc)))
   675	        return false;
   676	      if (unlikely (sidmap.get_count () > 0x8000))      /* assumption: a dict won't reference that many strings */
   677	        return false;
   678	      if (subset_charset)
   679	        offsets.charsetInfo.size = plan_subset_charset (acc, plan);
   680	
   681	      topdict_mod.reassignSIDs (sidmap);
   682	    }
   683	
   684	    /* String INDEX */
   685	    {
   686	      offsets.stringIndexInfo.offset = final_size;
   687	      offsets.stringIndexInfo.size = acc.stringIndex->calculate_serialized_size (offsets.stringIndexInfo.offSize, sidmap);
   688	      final_size += offsets.stringIndexInfo.size;
   689	    }
   690	
   691	    if (desubroutinize)
   692	    {
   693	      /* Flatten global & local subrs */
   694	      SubrFlattener<const OT::cff1::accelerator_subset_t, CFF1CSInterpEnv, CFF1CSOpSet_Flatten>
   695	                    flattener(acc, plan->glyphs, plan->drop_hints);
   696	      if (!flattener.flatten (subset_charstrings))
   697	        return false;
   698	
   699	      /* no global/local subroutines */
   700	      offsets.globalSubrsInfo.size = CFF1Subrs::calculate_serialized_size (1, 0, 0);
